('original:science--engineering-stem--coding-and-robotics-basics:science--engineering-stem--coding-and-robotics-basics--17',1,'{"question":"A robot''s left and right wheels turn at different speeds to make a curve. Which idea is being applied?","choices":["Differential drive control","Image compression","Data encryption","Chemical equilibrium"],"answer":0,"explanation":""}'::jsonb,'3f4885f7f96967f911becb53377efe2f','official',NULL,NULL,'Coding and Robotics Basics'),
('original:science--engineering-stem--coding-and-robotics-basics:science--engineering-stem--coding-and-robotics-basics--18',1,'{"question":"A remote-controlled robot responds only while a person holds a direction button. How does it differ from an autonomous robot?","choices":["It must have more sensors than an autonomous robot","It relies on a human operator for movement commands","It cannot use electric motors","It automatically makes every decision from sensor data"],"answer":1,"explanation":""}'::jsonb,'df76b0fd26818bc550b80c06b90d75df','official',NULL,NULL,'Coding and Robotics Basics'),
('original:science--engineering-stem--coding-and-robotics-basics:science--engineering-stem--coding-and-robotics-basics--19',1,'{"question":"A program''s obstacle sensor reading is sometimes late. Why can a fast robot be less safe than a slow one in the same course?","choices":["It receives more accurate readings at higher speed","Its actuators stop before a command is sent","It travels farther before the delayed reading can affect movement","Its algorithm no longer needs conditions"],"answer":2,"explanation":""}'::jsonb,'9cc904621de4fc6c17d33fb91e194e15','official',NULL,NULL,'Coding and Robotics Basics'),
('original:science--engineering-stem--coding-and-robotics-basics:science--engineering-stem--coding-and-robotics-basics--20',1,'{"question":"A robot arm misses the target because its claw closes before the arm reaches the object. What is the most direct code revision?","choices":["Add a second claw-close command at the start","Remove the arm movement command","Change the color of the target","Adjust the sequence or timing so the arm reaches the target before the claw closes"],"answer":3,"explanation":""}'::jsonb,'9feefdb1faea612b7bc9f0734987bb4a','official',NULL,NULL,'Coding and Robotics Basics'),
('original:science--engineering-stem--stem-careers-and-real-world-connections:science--engineering-stem--stem-careers-and-real-world-connections--1',1,'{"question":"Which professional most directly designs structures such as bridges and evaluates the forces they must withstand?","choices":["Civil engineer","Marine biologist","Epidemiologist","Astronomer"],"answer":0,"explanation":""}'::jsonb,'d27c89df004d8814d55f1229a37283e6','official',NULL,NULL,'STEM Careers and Real-World Connections'),
('original:science--engineering-stem--stem-careers-and-real-world-connections:science--engineering-stem--stem-careers-and-real-world-connections--2',1,'{"question":"A scientist studies how a new medicine affects cells in a controlled investigation. Which field is most directly related?","choices":["Urban planning","Biomedical science","Geology","Aerospace manufacturing"],"answer":1,"explanation":""}'::jsonb,'1573f19d3f5375e80ab72119f1d77a29','official',NULL,NULL,'STEM Careers and Real-World Connections'),
('original:science--engineering-stem--stem-careers-and-real-world-connections:science--engineering-stem--stem-careers-and-real-world-connections--3',1,'{"question":"What is a common difference between scientific inquiry and engineering design?","choices":["Science uses evidence, while engineering avoids testing","Engineering asks no questions about how systems work","Science often explains natural phenomena; engineering develops solutions to needs","Scientific work always produces a device"],"answer":2,"explanation":""}'::jsonb,'7ddf8f01771421348ee2d72676c32953','official',NULL,NULL,'STEM Careers and Real-World Connections'),
('original:science--engineering-stem--stem-careers-and-real-world-connections:science--engineering-stem--stem-careers-and-real-world-connections--4',1,'{"question":"A city wants to reduce flooding after heavy rain. Which team would most likely combine drainage design, land-use maps, and rainfall data?","choices":["Only professional athletes","Only graphic designers","A team that avoids local measurements","Civil engineers, planners, and environmental scientists"],"answer":3,"explanation":""}'::jsonb,'e424ae5f0623b527cc2fb6c920964788','official',NULL,NULL,'STEM Careers and Real-World Connections'),
('original:science--engineering-stem--stem-careers-and-real-world-connections:science--engineering-stem--stem-careers-and-real-world-connections--5',1,'{"question":"Why do many STEM projects benefit from collaboration across different specialties?","choices":["Different expertise can address connected parts of a complex problem","Team members can avoid sharing evidence","A single specialty always contains every needed skill","Collaboration eliminates the need to test a solution"],"answer":0,"explanation":""}'::jsonb,'3e75e68abac411be8bb6b52c947be26f','official',NULL,NULL,'STEM Careers and Real-World Connections'),
('original:science--engineering-stem--stem-careers-and-real-world-connections:science--engineering-stem--stem-careers-and-real-world-connections--6',1,'{"question":"An agricultural scientist compares crop growth under different watering schedules. Which skill is most important for a fair study?","choices":["Changing soil type and water amount together","Controlling other conditions and recording growth consistently","Selecting only the strongest-looking plant","Using a different measuring tool each day"],"answer":1,"explanation":""}'::jsonb,'43887e28155b6e39ce4093ee8de4c11b','official',NULL,NULL,'STEM Careers and Real-World Connections'),
('original:science--engineering-stem--stem-careers-and-real-world-connections:science--engineering-stem--stem-careers-and-real-world-connections--7',1,'{"question":"A data analyst sees that hospital visits rise during a heat wave. What should the analyst do before claiming heat caused the increase?","choices":["Assume the two trends prove cause and effect","Discard days when visits did not rise","Examine timing, comparison data, and other possible contributing factors","Replace data analysis with a personal opinion"],"answer":2,"explanation":""}'::jsonb,'b226349611f52ca2045a49ae7dffbef3','official',NULL,NULL,'STEM Careers and Real-World Connections'),
('original:science--engineering-stem--stem-careers-and-real-world-connections:science--engineering-stem--stem-careers-and-real-world-connections--8',1,'{"question":"Which role most directly helps create software that turns satellite measurements into maps?","choices":["Veterinary technician","Food stylist","Stage manager","Geospatial software developer"],"answer":3,"explanation":""}'::jsonb,'a87e1255d5fdfb8b10603d73e4837aea','official',NULL,NULL,'STEM Careers and Real-World Connections'),
('original:science--engineering-stem--stem-careers-and-real-world-connections:science--engineering-stem--stem-careers-and-real-world-connections--9',1,'{"question":"A biomedical engineer is designing a lightweight prosthetic hand. Which consideration belongs in the design evaluation?","choices":["Function, comfort, safety, cost, and access for intended users","Appearance alone","Whether the device uses the most parts","Whether the team can avoid feedback from users"],"answer":0,"explanation":""}'::jsonb,'fb82f2cadb6486b3e4d58060fb873400','official',NULL,NULL,'STEM Careers and Real-World Connections'),
('original:science--engineering-stem--stem-careers-and-real-world-connections:science--engineering-stem--stem-careers-and-real-world-connections--10',1,'{"question":"Why might an environmental scientist use a computer model of a watershed?","choices":["To replace all field observations permanently","To explore how changing conditions could affect water flow or quality","To guarantee every forecast is exact","To remove uncertainty from natural systems"],"answer":1,"explanation":""}'::jsonb,'910344df05c3ad435ae525e49ebb90d0','official',NULL,NULL,'STEM Careers and Real-World Connections'),
('original:science--engineering-stem--stem-careers-and-real-world-connections:science--engineering-stem--stem-careers-and-real-world-connections--11',1,'{"question":"A technician notices that a machine''s vibration increases over several weeks. Which response best uses STEM reasoning?","choices":["Wait for the machine to fail before recording evidence","Change several parts before identifying the problem","Collect consistent measurements and compare them with normal operating patterns","Ignore the trend if the machine still turns on"],"answer":2,"explanation":""}'::jsonb,'912913dd1a5133db384ba44e52af21a4','official',NULL,NULL,'STEM Careers and Real-World Connections'),
('original:science--engineering-stem--stem-careers-and-real-world-connections:science--engineering-stem--stem-careers-and-real-world-connections--12',1,'{"question":"What is one reason engineers document design decisions and test results?","choices":["Documentation guarantees the design cannot fail","It removes the need for technical communication","It replaces testing with record keeping","Others can understand, evaluate, reproduce, or improve the work"],"answer":3,"explanation":""}'::jsonb,'c724adb10d8ce5d32448365f087fe350','official',NULL,NULL,'STEM Careers and Real-World Connections'),
