('original:us-history--articles-of-confederation:us-history--articles-of-confederation--8',1,'{"question":"Why was national revenue difficult to collect under the Articles?","choices":["Congress collected only a national income tax","Congress controlled every state''s property tax","States were prohibited from contributing money","Congress relied on state contributions rather than direct national taxation"],"answer":3,"explanation":""}'::jsonb,'919d92c24b188dac1a45c4077ac8f76c','official',NULL,NULL,'Articles of Confederation'),
('original:us-history--articles-of-confederation:us-history--articles-of-confederation--9',1,'{"question":"Why did many Americans favor a weak central government initially?","choices":["They feared concentrated authority after experience with British rule","They wanted an American hereditary monarchy","They opposed cooperation among independent states","They sought to restore Parliament''s control"],"answer":0,"explanation":""}'::jsonb,'00adf463f1b7f5eda335453999e5cb5d','official',NULL,NULL,'Articles of Confederation'),
