('original:us-history--articles-of-confederation:us-history--articles-of-confederation--11',1,'{"question":"What was one achievement of the Confederation government?","choices":["Creating a permanent national income tax","Establishing rules for western territories and new states","Establishing the modern executive Cabinet","Giving women nationwide voting rights"],"answer":1,"explanation":""}'::jsonb,'a8c0046d24eede0e7395434fbafce7de','official',NULL,NULL,'Articles of Confederation'),
('original:us-history--articles-of-confederation:us-history--articles-of-confederation--12',1,'{"question":"What did Shays'' Rebellion reveal to critics of the Articles?","choices":["The need to abolish all state governments","The failure of a strong national presidency","The success of universal voting in every state","Problems responding to unrest under a weak national framework"],"answer":3,"explanation":""}'::jsonb,'c5c95eb0bb1e8cf930e6007b6f1a77b4','official',NULL,NULL,'Articles of Confederation'),
