('original:us-history--articles-of-confederation:us-history--articles-of-confederation--16',1,'{"question":"A state refuses Congress''s request for revenue. Which weakness does this illustrate?","choices":["Congress''s control of all state tax collections","A presidential veto of state budgets","Federal authority to replace state legislatures","Dependence on state cooperation for national funding"],"answer":3,"explanation":""}'::jsonb,'86bf5830b931d50cd71058520c1a15cc','official',NULL,NULL,'Articles of Confederation')
