('original:us-history--articles-of-confederation:us-history--articles-of-confederation--17',1,'{"question":"Which sequence orders these developments correctly?","choices":["Articles adopted, Articles fully ratified, Constitution implemented","Constitution implemented, Articles adopted, Articles fully ratified","Articles fully ratified, Constitution implemented, Articles adopted","Articles adopted, Constitution implemented, Articles fully ratified"],"answer":0,"explanation":""}'::jsonb,'a5b79ca953db4b0dffdd445f3270d416','official',NULL,NULL,'Articles of Confederation'),
('original:us-history--articles-of-confederation:us-history--articles-of-confederation--18',1,'{"question":"Which contrast between the Articles and Constitution is accurate?","choices":["The Articles gave the president greater powers than the Constitution","The Constitution eliminated national courts entirely","The Constitution created a separate national executive and stronger federal powers","The Articles created the current House and Senate"],"answer":2,"explanation":""}'::jsonb,'5b522060859565f3b258bfd21952beb2','official',NULL,NULL,'Articles of Confederation'),
