('original:us-history--articles-of-confederation:us-history--articles-of-confederation--20',1,'{"question":"Which evidence supports a balanced assessment of the Articles?","choices":["They established no national institutions at all","They solved every dispute among states permanently","They operated only after the Constitution was ratified","They provided a national framework but struggled with funding and coordination"],"answer":3,"explanation":""}'::jsonb,'588ac715ccc38fe0e8a756185b65f55f','official',NULL,NULL,'Articles of Confederation'),
