('original:us-history--early-republic:us-history--early-republic--4',1,'{"question":"Which protest challenged a federal excise tax on distilled spirits in 1794?","choices":["Shays'' Rebellion","Whiskey Rebellion","Bacon''s Rebellion","Dorr Rebellion"],"answer":1,"explanation":""}'::jsonb,'452b5356e4badd2365d3029c9b2a457d','official',NULL,NULL,'Early Republic'),
('original:us-history--early-republic:us-history--early-republic--5',1,'{"question":"What position did Washington announce toward war between Britain and France in 1793?","choices":["Neutrality","An alliance with France","An alliance with Britain","A declaration of war on both powers"],"answer":0,"explanation":""}'::jsonb,'bdd95ba2967b9e5585d2d9cb3c38947a','official',NULL,NULL,'Early Republic'),
('original:us-history--early-republic:us-history--early-republic--6',1,'{"question":"What was the XYZ Affair?","choices":["A court dispute over western land","A rebellion against state income taxes","A diplomatic controversy involving French demands for payments","A treaty purchasing Florida from Spain"],"answer":2,"explanation":""}'::jsonb,'9c50b473dd72ae674367c0dd25b2298f','official',NULL,NULL,'Early Republic'),
('original:us-history--early-republic:us-history--early-republic--7',1,'{"question":"Which laws passed in 1798 included restrictions on criticism of the federal government?","choices":["Navigation Acts","Intolerable Acts","Townshend Acts","Alien and Sedition Acts"],"answer":3,"explanation":""}'::jsonb,'d23c7afb662bc02fad5bf8d1d0158dbb','official',NULL,NULL,'Early Republic'),
('original:us-history--early-republic:us-history--early-republic--8',1,'{"question":"Why did Hamilton favor federal assumption of state Revolutionary War debts?","choices":["To transfer federal powers to colonial governors","To strengthen national credit and support for the new government","To cancel every debt without repayment","To prohibit future borrowing by private businesses"],"answer":1,"explanation":""}'::jsonb,'fb10bbf205a98bc3c8b161dd25474fb6','official',NULL,NULL,'Early Republic'),
