('original:us-history--early-republic:us-history--early-republic--10',1,'{"question":"What did Washington''s response to the Whiskey Rebellion demonstrate?","choices":["Congress could no longer pass taxes","States could ignore any federal law","The federal government could enforce its laws","The president had abolished civilian courts"],"answer":2,"explanation":""}'::jsonb,'b335bb24012c3fe81c0134bc9a489f3d','official',NULL,NULL,'Early Republic'),
