('original:government--bill-of-rights:government--bill-of-rights--10',1,'{"question":"What does the right to petition allow people to do?","choices":["Require courts to approve every personal request","Ignore laws they disagree with","Ask government to address grievances","Remove officials without legal procedures"],"answer":2,"explanation":""}'::jsonb,'c1f93e38eea086ee44002667af2b0c7c','official',NULL,NULL,'Bill of Rights'),
