('original:government--bill-of-rights:government--bill-of-rights--20',1,'{"question":"Which comparison distinguishes the First and Sixth Amendments?","choices":["Both establish presidential election procedures","The First creates Congress; the Sixth creates the Cabinet","Both reserve all federal powers to states","The First protects expression; the Sixth protects rights in criminal prosecutions"],"answer":3,"explanation":""}'::jsonb,'8af2aaed93c4ea8803749ad69aa1285b','official',NULL,NULL,'Bill of Rights'),
