('original:government--constitutional-amendments:government--constitutional-amendments--13',1,'{"question":"How did the Twenty-First Amendment relate to the Eighteenth Amendment?","choices":["It repealed the earlier prohibition amendment","It extended prohibition to additional products","It made prohibition a permanent unamendable rule","It transferred prohibition enforcement to foreign courts"],"answer":0,"explanation":""}'::jsonb,'59b9d071df3ae8fe92fff0c370e0f32e','official',NULL,NULL,'Constitutional Amendments'),
('original:government--constitutional-amendments:government--constitutional-amendments--14',1,'{"question":"What did the Twenty-Fourth Amendment prohibit in federal elections?","choices":["The use of secret ballots","Poll taxes as a condition of voting","The election of candidates without party membership","Registration procedures for eligible voters"],"answer":1,"explanation":""}'::jsonb,'0adee18d84a6371a5092aa2e9137bb84','official',NULL,NULL,'Constitutional Amendments'),
('original:government--constitutional-amendments:government--constitutional-amendments--15',1,'{"question":"What did the Twenty-Third Amendment provide for the District of Columbia?","choices":["Full statehood under the Constitution","Two voting senators and no electors","The power to ratify amendments as a state","Participation in presidential elections through appointed electors"],"answer":3,"explanation":""}'::jsonb,'46c185741c74fc78203d2fc93ea064f9','official',NULL,NULL,'Constitutional Amendments'),
('original:government--constitutional-amendments:government--constitutional-amendments--16',1,'{"question":"A proposal passes both houses of Congress by two-thirds, but only half the states ratify it. What is its status?","choices":["It becomes law after presidential approval","It takes effect only in the ratifying states","It has not become a constitutional amendment","It automatically goes to the Supreme Court for adoption"],"answer":2,"explanation":""}'::jsonb,'49a960ceccc04e8081bf26abab21bdd8','official',NULL,NULL,'Constitutional Amendments')
