('original:government--constitutional-amendments:government--constitutional-amendments--17',1,'{"question":"Which alternative to congressional proposal is authorized by Article V?","choices":["A convention called after applications from two-thirds of state legislatures","A national petition signed by one million voters","A presidential proclamation approved by cabinet members","A unanimous decision of the federal courts of appeals"],"answer":0,"explanation":""}'::jsonb,'dc1f21898f68be4e0568bf0a7cc3fe03','official',NULL,NULL,'Constitutional Amendments'),
('original:government--constitutional-amendments:government--constitutional-amendments--18',1,'{"question":"Which distinction between an ordinary federal law and a constitutional amendment is correct?","choices":["Ordinary laws require ratification by three-fourths of states","Amendments alter the constitutional framework through a separate process","Ordinary laws cannot be repealed after presidential signature","Amendments require the same simple-majority procedure as bills"],"answer":1,"explanation":""}'::jsonb,'25871d3a99f9926965a3193eb5dabf52','official',NULL,NULL,'Constitutional Amendments'),
('original:government--constitutional-amendments:government--constitutional-amendments--19',1,'{"question":"Which sequence correctly orders these voting-rights amendments by ratification?","choices":["Twenty-Sixth → Nineteenth → Fifteenth","Nineteenth → Fifteenth → Twenty-Sixth","Fifteenth → Nineteenth → Twenty-Sixth","Fifteenth → Twenty-Sixth → Nineteenth"],"answer":2,"explanation":""}'::jsonb,'98fd5e5894f085dac8bd6e9272b15af2','official',NULL,NULL,'Constitutional Amendments'),
('original:government--constitutional-amendments:government--constitutional-amendments--20',1,'{"question":"A student says ratifying the Fifteenth Amendment immediately ended racial voting barriers. Which evidence best challenges this claim?","choices":["The amendment''s number comes after fourteen","Presidential elections continued after ratification","States retained elected legislatures","Discriminatory practices continued despite the constitutional prohibition"],"answer":3,"explanation":""}'::jsonb,'72203bbd0a6a8ef244d660c63078f45e','official',NULL,NULL,'Constitutional Amendments'),
('original:government--civil-liberties:government--civil-liberties--1',1,'{"question":"What are civil liberties?","choices":["Benefits granted only to public officials","Responsibilities of military commanders","Protections for individual freedom against government interference","Powers reserved exclusively for political parties"],"answer":2,"explanation":""}'::jsonb,'3f8375d9fa8995aa4bf39dc6aa2638ea','official',NULL,NULL,'Civil Liberties'),
('original:government--civil-liberties:government--civil-liberties--2',1,'{"question":"Which amendment protects speech, press, assembly, petition, and religious freedom?","choices":["First","Fourth","Sixth","Tenth"],"answer":0,"explanation":""}'::jsonb,'7e45700d3d9e4d41e09a2df0d0f3a6e6','official',NULL,NULL,'Civil Liberties'),
('original:government--civil-liberties:government--civil-liberties--3',1,'{"question":"Which constitutional protection concerns unreasonable government searches and seizures?","choices":["Seventh Amendment","Third Amendment","Ninth Amendment","Fourth Amendment"],"answer":3,"explanation":""}'::jsonb,'2674fa8b08552fc9779205f2991b8580','official',NULL,NULL,'Civil Liberties'),
('original:government--civil-liberties:government--civil-liberties--4',1,'{"question":"Which amendment includes a protection against compelled self-incrimination?","choices":["Second","Fifth","Eighth","Tenth"],"answer":1,"explanation":""}'::jsonb,'1685b1b55a70b89ce55f14923d946306','official',NULL,NULL,'Civil Liberties'),
('original:government--civil-liberties:government--civil-liberties--5',1,'{"question":"Which amendment protects the right to assistance of counsel in criminal prosecutions?","choices":["Sixth","Third","Seventh","Ninth"],"answer":0,"explanation":""}'::jsonb,'9fa2105c1f477f58f5f2870f0763dacc','official',NULL,NULL,'Civil Liberties'),
('original:government--civil-liberties:government--civil-liberties--6',1,'{"question":"What is prior restraint in a freedom-of-expression dispute?","choices":["A penalty imposed after a publication is found unlawful","A private reader''s decision not to purchase a newspaper","Government action preventing expression before it occurs","A publisher''s voluntary correction of an inaccurate report"],"answer":2,"explanation":""}'::jsonb,'daa8e8eec2b0609d04e768b39f6dd149','official',NULL,NULL,'Civil Liberties'),
('original:government--civil-liberties:government--civil-liberties--7',1,'{"question":"What does the Free Exercise Clause concern?","choices":["Congress''s power to regulate interstate commerce","A governor''s authority to set tax rates","A court''s authority to schedule trials","Protection of religious belief and practice"],"answer":3,"explanation":""}'::jsonb,'e85f011c1a8a1054de032571ac344a02','official',NULL,NULL,'Civil Liberties'),
('original:government--civil-liberties:government--civil-liberties--8',1,'{"question":"What is the basic purpose of the Establishment Clause?","choices":["To select one national religious leader","To limit government establishment of religion","To require citizens to join a religious organization","To remove religious speech from private homes"],"answer":1,"explanation":""}'::jsonb,'e4f392a073e7f4598a8384b4e10458f9','official',NULL,NULL,'Civil Liberties'),
('original:government--civil-liberties:government--civil-liberties--9',1,'{"question":"Why is criticism of public officials an important protected form of speech?","choices":["It helps people debate policy and hold government accountable","It guarantees critics will win every election","It removes the need for evidence in public discussion","It gives critics immunity from every generally applicable law"],"answer":0,"explanation":""}'::jsonb,'d1217487aaaf7368bf7e1a3fc246d3c0','official',NULL,NULL,'Civil Liberties'),
('original:government--civil-liberties:government--civil-liberties--10',1,'{"question":"How has the Fourteenth Amendment affected many Bill of Rights protections?","choices":["It repealed all protections involving criminal trials","It restricted them to residents of the national capital","It has helped apply many protections to state and local governments","It made those protections optional for each state legislature"],"answer":2,"explanation":""}'::jsonb,'c60ea90921135e19ae123b983fa88dac','official',NULL,NULL,'Civil Liberties'),
('original:government--civil-liberties:government--civil-liberties--11',1,'{"question":"Why does the Fourth Amendment not prohibit every government search?","choices":["It applies only when a suspect admits guilt","It protects property but never people","It gives police unlimited authority inside homes","It prohibits unreasonable searches rather than all searches"],"answer":3,"explanation":""}'::jsonb,'9a827c78b5281780d90fef5f69247596','official',NULL,NULL,'Civil Liberties'),
('original:government--civil-liberties:government--civil-liberties--12',1,'{"question":"What is the purpose of due process protections?","choices":["To guarantee that every accused person is acquitted","To require fair procedures before government deprives a person of protected interests","To let officials punish people without a hearing","To transfer every criminal case to the legislature"],"answer":1,"explanation":""}'::jsonb,'49d0af81b32d19f20f5ee443ad93ce51','official',NULL,NULL,'Civil Liberties'),
('original:government--civil-liberties:government--civil-liberties--13',1,'{"question":"Why is the right to peaceful assembly important in civic life?","choices":["It allows people to gather and express shared concerns","It authorizes private groups to replace elected governments","It permits participants to disregard all safety rules","It guarantees that officials must adopt every protest demand"],"answer":0,"explanation":""}'::jsonb,'1e69cb2032b795b8983a76b1fdcd562a','official',NULL,NULL,'Civil Liberties'),
('original:government--civil-liberties:government--civil-liberties--14',1,'{"question":"What does freedom of the press protect most directly?","choices":["A publisher''s right to receive guaranteed government profits","An editor''s authority to appoint public officials","The ability to publish information and opinions without improper government suppression","A newspaper''s exemption from every civil lawsuit"],"answer":2,"explanation":""}'::jsonb,'f342fb7ba3a3e2f81d355daa62ad40bf','official',NULL,NULL,'Civil Liberties'),
('original:government--civil-liberties:government--civil-liberties--15',1,'{"question":"Why can courts face difficult questions involving civil liberties?","choices":["Constitutional text eliminates every disagreement","Civil liberties apply only when everyone agrees","Courts cannot interpret any constitutional provision","Individual freedoms may interact with other rights and public interests"],"answer":3,"explanation":""}'::jsonb,'69ea4bad699baf2d688ab5bf1c0fadf8','official',NULL,NULL,'Civil Liberties'),
('original:government--civil-liberties:government--civil-liberties--16',1,'{"question":"A city denies a peaceful group''s park permit solely because officials dislike its message. Which concern is most directly raised?","choices":["A change in congressional apportionment","Viewpoint discrimination against protected expression","A conflict over military command","A dispute over state boundary lines"],"answer":1,"explanation":""}'::jsonb,'123fdf0faf49191cc3e1ba2662cdffdb','official',NULL,NULL,'Civil Liberties'),
('original:government--civil-liberties:government--civil-liberties--17',1,'{"question":"A government forces an accused person to testify against themselves in a criminal case. Which protection is directly implicated?","choices":["The Fifth Amendment''s self-incrimination protection","The Third Amendment''s quartering restriction","The Seventh Amendment''s civil-jury protection","The Tenth Amendment''s reservation of powers"],"answer":0,"explanation":""}'::jsonb,'771e268dc72c4303e306903c38964cef','official',NULL,NULL,'Civil Liberties'),
('original:government--civil-liberties:government--civil-liberties--18',1,'{"question":"Which statement best distinguishes a civil liberty from a guaranteed favorable outcome?","choices":["Freedom of speech guarantees public agreement","The right to counsel guarantees acquittal","Protected participation does not guarantee that one''s preferred policy will be adopted","Freedom of the press guarantees that every report is accurate"],"answer":2,"explanation":""}'::jsonb,'699158cfec7fd5bcc98a315d2b8c0bcc','official',NULL,NULL,'Civil Liberties'),
('original:government--civil-liberties:government--civil-liberties--19',1,'{"question":"A state prosecutes a person under its own criminal laws. Why might federal constitutional protections still matter?","choices":["State courts are exempt from every constitutional requirement","Only federal officials can investigate crimes","State legislation automatically overrides constitutional rights","Many federal rights also constrain state government through incorporation"],"answer":3,"explanation":""}'::jsonb,'cf3445570c281b763be42cfec75e7ea6','official',NULL,NULL,'Civil Liberties'),
('original:government--civil-liberties:government--civil-liberties--20',1,'{"question":"A private club disagrees with a member''s opinion. What fact should be checked before treating the dispute as a First Amendment violation?","choices":["Whether the opinion is popular with all club members","Whether the challenged action involves government rather than only private conduct","Whether the speaker has voted in every election","Whether the club uses printed rather than digital messages"],"answer":1,"explanation":""}'::jsonb,'66ca068f1e42a3b9f59d9f43febdbd92','official',NULL,NULL,'Civil Liberties'),
('original:government--political-parties:government--political-parties--1',1,'{"question":"What is a political party?","choices":["A court that reviews election disputes","An organization seeking to win elections and influence government","A government office issuing driver''s licenses","A business that prints all official ballots"],"answer":1,"explanation":""}'::jsonb,'609e994bea44913a5ef5b276d0d48e0f','official',NULL,NULL,'Political Parties'),
('original:government--political-parties:government--political-parties--2',1,'{"question":"What is a party platform?","choices":["A statement of the party''s policy positions and goals","A list of every voter in the country","A constitutional rule for counting electoral votes","A court order establishing legislative districts"],"answer":0,"explanation":""}'::jsonb,'9d617f7c1cacadc7865479fc0f6b9b35','official',NULL,NULL,'Political Parties'),
