('original:government--local-government:government--local-government--14',1,'{"question":"Why can local government structures vary between states?","choices":["Every town is an independent sovereign country","The Constitution requires identical county governments","States establish different laws and authorizations for local institutions","Local offices exist outside all legal frameworks"],"answer":2,"explanation":""}'::jsonb,'3f2b3299dbe848ad62ab6c65b42924ca','official',NULL,NULL,'Local Government'),
('original:government--local-government:government--local-government--15',1,'{"question":"Why do public records and open meetings matter for local accountability?","choices":["They guarantee agreement with every decision","They remove the need for elected officials","They give residents automatic access to legally confidential information","They help residents examine how public decisions are made"],"answer":3,"explanation":""}'::jsonb,'061246b7f2a2f225f69f599315f17266','official',NULL,NULL,'Local Government'),
